    '. Cada campeonato nuevo empieza con ellas, pero cada campeonato puede tener las suyas (se cambian en Campeonato → Configuración).' => '. Cada novo campeonato começa com elas, mas cada campeonato pode ter as suas próprias (alteradas em Campeonato → Configurações).',
    '. Cada cono suma {n} s automáticamente. Toque' => '. Cada cone soma {n} s automaticamente. Toque em',
    '. Con' => '. Com',
    '. Cuando una liga se registra con su enlace o su código (o usted la asigna en Ligas → Editar), cada pago de suscripción que registre en' => '. Quando uma liga se registra com o seu link ou código (ou você a atribui em Ligas → Editar), cada pagamento de assinatura que você registrar em',
    '. Deje vacío a quien no jugó.' => '. Deixe em branco quem não jogou.',
    '. Ejemplo, sprint de {n} m (gana el menor), {n} a {n} años: amarillo desde {n} s y verde desde {n} s.' => '. Exemplo: sprint de {n} m (vence o menor), {n} a {n} anos: amarelo a partir de {n} s e verde a partir de {n} s.',
    '. El ganador pasa solo a la ronda siguiente.' => '. O vencedor passa automaticamente para a rodada seguinte.',
    '. El interesado llena "Solicitar demo" y usted decide a quién le crea la cuenta (menú' => '. O interessado preenche "Solicitar demonstração" e você decide para quem criar a conta (menu',
    '. El público lo ve en la pestaña' => '. O público vê na aba',
    '. En el celular:' => '. No celular:',
    '. En el celular: menú ⋮ → Compartir → Imprimir → Guardar como PDF.' => '. No celular: menu ⋮ → Compartilhar → Imprimir → Salvar como PDF.',
    '. Estos proveedores aplican medidas de seguridad reconocidas internacionalmente y actúan solo como proveedores de infraestructura: no usan los datos para fines propios. Al aceptar esta política, usted autoriza esta transferencia internacional, que es necesaria para que el servicio funcione.' => '. Esses provedores aplicam medidas de segurança reconhecidas internacionalmente e atuam apenas como provedores de infraestrutura: não usam os dados para fins próprios. Ao aceitar esta política, você autoriza essa transferência internacional, necessária para que o serviço funcione.',
    '. Falta que la federación lo apruebe.' => '. Falta a federação aprová-lo.',
    '. Formulario público:' => '. Formulário público:',
    '. Funciona sin internet y sincroniza cuando vuelve la señal.' => '. Funciona sem internet e sincroniza quando o sinal volta.',
    '. La cédula se valida ({n} números) o se acepta pasaporte.' => '. O documento é validado ({n} números) ou aceita-se passaporte.',
    '. La federación ve sus números, sus partidos y puede poner sanciones federativas que se aplican en sus campeonatos. Sus torneos siguen siendo solo suyos.' => '. A federação vê os seus números, as suas partidas e pode aplicar punições federativas que valem nos seus campeonatos. Seus torneios continuam sendo somente seus.',
    '. La liga la abre en cada campeonato con una fecha límite.' => '. A liga a abre em cada campeonato com uma data limite.',
    '. Le pediremos su cédula para comprobar que es el titular. Se responderá en el plazo que establece la ley ({n} días).' => '. Pediremos o seu documento para comprovar que você é o titular. A resposta será dada no prazo estabelecido por lei ({n} dias).',
    '. Los árbitros y delegados se crean en Árbitros y en cada Equipo.' => '. Os árbitros e delegados são criados em Árbitros e em cada Equipe.',
    '. Mientras más claro, más rápido lo podemos evaluar y desarrollar. Le avisamos aquí cuando tengamos novedades.' => '. Quanto mais claro, mais rápido poderemos avaliá-lo e desenvolvê-lo. Avisaremos você aqui quando tivermos novidades.',
    '. No ve los pagos de los alumnos; sí ve' => '. Não vê os pagamentos dos alunos; vê',
    '. Para salir de un panel y entrar a otro, vuelva a esta página.' => '. Para sair de um painel e entrar em outro, volte a esta página.',
    '. Quien entra por su enlace queda anotado como recomendado por usted.' => '. Quem entra pelo seu link fica registrado como indicado por você.',
    '. Recibimos su solicitud de demo para' => '. Recebemos o seu pedido de demonstração para',
