    '. Se rige por la Ley Orgánica de Protección de Datos Personales del Ecuador (LOPDP) y su Reglamento.' => '. Rege-se pela Lei Orgânica de Proteção de Dados Pessoais do Equador (LOPDP) e seu Regulamento.',
    '. Si deja vacío y pone el estado "Finalizado", se llenan solos.' => '. Se deixar em branco e definir o status "Finalizado", são preenchidos automaticamente.',
    '. Si no compitió, cambie el estado (DNS, DNF o DQ). Los puestos se calculan solos.' => '. Se não competiu, altere o status (DNS, DNF ou DQ). As colocações são calculadas automaticamente.',
    '. Si quiere vender las entradas de sus partidos (con QR, tarjeta o transferencia, taquilla, cortesías y parqueadero), actívela con la casilla en' => '. Se quiser vender os ingressos das suas partidas (com QR, cartão ou transferência, bilheteria, cortesias e estacionamento), ative-a com a caixa de seleção em',
