    'Al cargar los tiempos, en cada etapa se marca cuántas veces se aplicó cada una y el sistema suma (o resta) los segundos. Use un valor negativo para una bonificación (ej: meta volante −{n}). Si cambia un valor, las clasificaciones se recalculan.' => 'Ao carregar os tempos, em cada etapa marca-se quantas vezes cada uma foi aplicada e o sistema soma (ou subtrai) os segundos. Use um valor negativo para uma bonificação (ex.: sprint intermediário −{n}). Se alterar um valor, as classificações são recalculadas.',
