    'Con el plan' => 'Com o plano',
    'Con el plan Profesional imprime el fixture completo de cada campeonato (con o sin resultados) y ve el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces, que se llenan solos con los clasificados.' => 'Com o plano Profissional, você imprime a tabela de jogos completa de cada campeonato (com ou sem resultados) e vê o esquema de todo o torneio desde o primeiro dia: grupos, rodadas e a chave da fase final com os confrontos, que se preenchem sozinhos com os classificados.',
    'Con este enlace, cualquiera agrega todos los partidos del campeonato al calendario de su celular (y se actualiza solo). Cada equipo tiene el suyo en su página pública.' => 'Com este link, qualquer pessoa adiciona todas as partidas do campeonato ao calendário do celular (e ele se atualiza sozinho). Cada equipe tem o seu na sua página pública.',
    'Con la misma cédula se agrupan hermanos (descuento).' => 'Com o mesmo documento, os irmãos são agrupados (desconto).',
