    'Cualquiera' => 'Qualquer',
    'Cuando la organización ingresa en el sistema los datos de otra persona (por ejemplo, al inscribir a un jugador o importar una lista), declara contar con la autorización de esa persona o de su representante, y esa declaración también queda registrada.' => 'Quando a organização insere no sistema os dados de outra pessoa (por exemplo, ao inscrever um jogador ou importar uma lista), declara ter a autorização dessa pessoa ou do seu responsável, e essa declaração também fica registrada.',
    'Cuando las clases tengan ejercicios, aquí verá cuánto tiempo fue técnico, táctico, físico o juego.' => 'Quando as aulas tiverem exercícios, aqui você verá quanto tempo foi técnico, tático, físico ou jogo.',
    'Cuando se juega cada partido, el ganador pasa solo a la siguiente ronda (en empate, cuentan los penales). Si corrige un resultado, el clasificado se corrige también.' => 'Quando cada partida é jogada, o vencedor passa automaticamente para a rodada seguinte (em caso de empate, contam os pênaltis). Se você corrigir um resultado, o classificado também é corrigido.',
    'Cuando un alumno está en otro grupo (otro deporte), esa mensualidad lleva este descuento.' => 'Quando um aluno está em outra turma (outro esporte), essa mensalidade recebe este desconto.',
    'Cuartos de final' => 'Quartas de final',
    'Cuartos, semifinal y final se arman solos con la tabla, y el ganador avanza solo.' => 'Quartas de final, semifinal e final são montadas sozinhas com a classificação, e o vencedor avança sozinho.',
    'Cuatro jugadores en un cuadrado de {n} × {n} m mantienen el balón; uno en el centro intenta recuperarlo. Quien pierde el balón entra al medio.' => 'Quatro jogadores em um quadrado de {n} × {n} m mantêm a bola; um no centro tenta recuperá-la. Quem perde a bola vai para o meio.',
