    'El' => 'O',
    'El archivo está vacío: debe tener la fila de títulos y al menos una fila con datos.' => 'O arquivo está vazio: deve ter a linha de títulos e pelo menos uma linha com dados.',
    'El archivo tiene más de' => 'O arquivo tem mais de',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el objetivo es pasar la línea media con control.' => 'O goleiro inicia com os defensores contra {n} ou {n} atacantes que pressionam; o objetivo é passar da linha do meio com controle.',
    'El arquero inicia con los defensores contra {n} o {n} delanteros que presionan; el …' => 'O goleiro inicia com os defensores contra {n} ou {n} atacantes que pressionam; o …',
    'El asistente' => 'O assistente',
    'El asistente nunca puede crear ni cambiar usuarios. Puede cambiar estos permisos cuando quiera; valen desde la siguiente página que abra.' => 'O assistente nunca pode criar nem alterar usuários. Você pode alterar estas permissões quando quiser; elas valem a partir da próxima página que ele abrir.',
    'El cliente le escribe aquí para confirmar o pagar.' => 'O cliente escreve para você aqui para confirmar ou pagar.',
    'El cobro con tarjeta se está terminando de conectar con Plux. Ya puede dejarlo configurado; el botón de pago aparecerá cuando esté listo.' => 'A cobrança com cartão está sendo finalizada com a Plux. Você já pode deixá-la configurada; o botão de pagamento aparecerá quando estiver pronto.',
    'El código' => 'O código',
    'El delegado sube la foto de su transferencia y el recibo sale al aprobarla.' => 'O delegado envia a foto da transferência e o recibo é emitido ao aprová-la.',
    'El enlace' => 'O link',
    'El entrenador pasa desde afuera del área; el jugador controla orientado hacia el arco y remata en máximo 2 toques.' => 'O treinador passa de fora da área; o jogador domina orientado para o gol e finaliza em no máximo 2 toques.',
    'El equipo' => 'A equipe',
    'El examen está cerrado. Ábralo de nuevo para corregir resultados.' => 'O exame está encerrado. Reabra-o para corrigir os resultados.',
    'El examen está cerrado. Ábralo de nuevo para inscribir.' => 'O exame está encerrado. Reabra-o para inscrever.',
    'El fixture completo de cada campeonato en PDF (con resultados o en blanco para llenar a mano) y el esquema de todo el torneo desde el primer día: grupos, jornadas y la llave de la fase final con los cruces (1° Grupo A vs 2° Grupo B), que se llenan solos con los clasificados.' => 'A tabela de jogos completa de cada campeonato em PDF (com resultados ou em branco para preencher à mão) e o esquema de todo o torneio desde o primeiro dia: grupos, rodadas e a chave da fase final com os confrontos (1° Grupo A vs 2° Grupo B), que se preenchem sozinhos com os classificados.',
    'El ganador de cada partido pasa solo a la siguiente ronda.' => 'O vencedor de cada partida passa automaticamente para a rodada seguinte.',
    'El idioma con el que se abre su página para el público. Cada visitante (y cada usuario del panel) puede cambiarlo con el botón 🌐 de arriba.' => 'O idioma em que a sua página abre para o público. Cada visitante (e cada usuário do painel) pode alterá-lo com o botão 🌐 acima.',
    'El informe de desarrollo reúne la asistencia, los gráficos de tests (comparados con su categoría), la evaluación técnica, las insignias, las metas y el comentario del profesor del trimestre. La familia también lo ve en su portal y lo puede guardar en PDF.' => 'O relatório de desenvolvimento reúne a presença, os gráficos de testes (comparados com a categoria), a avaliação técnica, as insígnias, as metas e o comentário do treinador do trimestre. A família também o vê no seu portal e pode salvá-lo em PDF.',
    'El informe del árbitro' => 'O relatório do árbitro',
    'El jugador autorizó' => 'O jogador autorizou',
    'El jugador no insultó al árbitro; pedimos revisar el video.' => 'O jogador não xingou o árbitro; pedimos para revisar o vídeo.',
    'El lector' => 'O leitor',
    'El pago con tarjeta no se completó.' => 'O pagamento com cartão não foi concluído.',
