    'El profesor dio la clase' => 'O treinador deu a aula',
    'El profesor planifica las clases por adelantado con la biblioteca de ejercicios de la escuela; cada clase guarda ejercicios, minutos, intensidad, fotos y una nota para cada alumno, y los padres ven el diario de entrenamientos de su hijo.' => 'O professor planeja as aulas com antecedência usando a biblioteca de exercícios da escola; cada aula guarda exercícios, minutos, intensidade, fotos e uma nota para cada aluno, e os pais veem o diário de treinos do filho.',
    'El profesor toma lista en segundos y anota el plan de la clase.' => 'O professor faz a chamada em segundos e anota o plano da aula.',
    'El público reserva sus canchas por horas desde el celular y el cobro entra a finanzas.' => 'O público reserva as quadras por hora pelo celular e a cobrança entra nas finanças.',
