    'El que corresponda por su edad' => 'O que corresponder à sua idade',
    'El que está en curso' => 'O que está em andamento',
    'El representante ve en su celular la asistencia, los pagos, las evaluaciones, la libreta y el carnet de sus hijos, y puede subir el comprobante de pago.' => 'O responsável vê no celular a presença, os pagamentos, as avaliações, o boletim e a carteirinha dos filhos, e pode enviar o comprovante de pagamento.',
    'El semáforo de cada resultado sale solo:' => 'O semáforo de cada resultado aparece sozinho:',
    'El sistema completo para administrar tu liga de fútbol' => 'O sistema completo para administrar sua liga de futebol',
    'El sistema completo para su escuela deportiva' => 'O sistema completo para a sua escola esportiva',
    'El sistema le avisa por Telegram cuando alguien pide una demo, cuando a una demo le quedan {n} días (día {n}) y el día que vence (día {n}), con el mensaje de WhatsApp listo para enviar.' => 'O sistema avisa você pelo Telegram quando alguém pede uma demonstração, quando faltam {n} dias para uma demonstração acabar (dia {n}) e no dia em que vence (dia {n}), com a mensagem de WhatsApp pronta para enviar.',
    'El sistema pone a cada alumno en su categoría por edad (Sub-{n}, Sub-{n}, Sub-{n}…) o en grupos abiertos.' => 'O sistema coloca cada aluno na sua categoria por idade (Sub-{n}, Sub-{n}, Sub-{n}…) ou em turmas abertas.',
    'El sistema reparte horarios, canchas y árbitros sin choques, o lo hace usted a mano.' => 'O sistema distribui horários, quadras e árbitros sem conflitos, ou você faz isso manualmente.',
    'El sistema reparte los equipos al azar y puede generar el fixture de una vez.' => 'O sistema distribui as equipes por sorteio e pode gerar a tabela de jogos de uma vez.',
    'El sistema reparte los partidos en las canchas y horarios que usted indique, sin que un equipo o un árbitro tenga dos partidos a la vez, alternando a los equipos entre horarios temprano y tarde y repartiendo los partidos entre los árbitros. Primero ve la propuesta y luego decide si la guarda.' => 'O sistema distribui as partidas nas quadras e horários que você indicar, sem que uma equipe ou um árbitro tenha duas partidas ao mesmo tempo, alternando as equipes entre horários cedo e tarde e distribuindo as partidas entre os árbitros. Primeiro você vê a proposta e depois decide se a salva.',
    'El sistema suma lo que se le debe a cada árbitro por los partidos jugados, según su función (central, asistente, cuarto). El valor por partido se pone en cada campeonato:' => 'O sistema soma o que é devido a cada árbitro pelas partidas disputadas, conforme a sua função (central, assistente, quarto árbitro). O valor por partida é definido em cada campeonato:',
    'El sistema ya está en inglés, francés, portugués e italiano: use el botón 🌐 de la barra de arriba. Elija el idioma de su página pública en Parámetros.' => 'O sistema já está em inglês, francês, português e italiano: use o botão 🌐 da barra superior. Escolha o idioma da sua página pública em Configurações.',
    'El video pesa más de' => 'O vídeo tem mais de',
    'El vocal abre este enlace en su' => 'O mesário abre este link no seu',
    'El vocal escanea el carnet y ve la foto:' => 'O mesário escaneia a carteirinha e vê a foto:',
    'El vocal escanea el carnet y ve la foto: se acabaron las suplantaciones.' => 'O mesário escaneia a carteirinha e vê a foto: acabaram as falsificações de identidade.',
    'El vocal escanea este QR en la cancha. La hora en vivo demuestra que no es una captura de pantalla.' => 'O mesário escaneia este QR na quadra. A hora ao vivo comprova que não é uma captura de tela.',
    'El vocal marca desde el celular y los hinchas ven el marcador al instante en la página de la liga.' => 'O mesário marca pelo celular e os torcedores veem o placar na hora na página da liga.',
    'El vocal registra goles, tarjetas, cambios y reloj desde el celular (funciona aunque se caiga el internet). El público ve el marcador en vivo, se escanea el carnet QR y sale la hoja de vocalía en PDF.' => 'O mesário registra gols, cartões, substituições e cronômetro pelo celular (funciona mesmo se a internet cair). O público vê o placar ao vivo, a carteirinha QR é escaneada e a súmula sai em PDF.',
    'El árbitro' => 'O árbitro',
    'El árbitro todavía no ha llenado el informe.' => 'O árbitro ainda não preencheu o relatório.',
    'El último set (ej:' => 'O último set (ex.:',
