    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el forma de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Esta é a lista que a sua escola usa, em ordem da primeira à última. Você pode alterar o grau, o nome, as cores, a ponta e a forma de cada faixa, ou desmarcar as que não usa. A ordem define qual é a «próxima faixa» de cada aluno.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el kata de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Esta é a lista que a sua escola usa, em ordem da primeira à última. Você pode alterar o grau, o nome, as cores, a ponta e o kata de cada faixa, ou desmarcar as que não usa. A ordem define qual é a «próxima faixa» de cada aluno.',
    'Esta es la lista que usa su escuela, en orden del primero al último. Puede cambiar el grado, el nombre, los colores, la punta y el poomsae de cada cinturón, o desmarcar los que no usa. El orden decide cuál es el «próximo cinturón» de cada alumno.' => 'Esta é a lista que a sua escola usa, em ordem da primeira à última. Você pode alterar o grau, o nome, as cores, a ponta e o poomsae de cada faixa, ou desmarcar as que não usa. A ordem define qual é a «próxima faixa» de cada aluno.',
