    'Exclusivo del plan Profesional: imprima el fixture completo de cada campeonato (con resultados o en blanco para llenar a mano) y vea el esquema de todo el torneo desde el primer día, con la llave de la fase final que se llena sola con los clasificados. Está en cada campeonato → 2. Fixture y resultados.' => 'Exclusivo do plano Profissional: imprima a tabela de jogos completa de cada campeonato (com resultados ou em branco para preencher à mão) e veja o esquema de todo o torneio desde o primeiro dia, com a chave da fase final que se preenche sozinha com os classificados. Fica em cada campeonato → 2. Tabela de jogos e resultados.',
