    'La foto' => 'A foto',
    'La foto siempre se usa en el carnet y en la vocalía para verificar identidad. La cédula completa y los datos del representante nunca se publican.' => 'A foto é sempre usada na carteirinha e na súmula para verificar a identidade. O documento completo e os dados do responsável nunca são publicados.',
    'La inscripción en línea está' => 'A inscrição on-line está',
    'La liga de demostración no se cuenta. "Ingreso mensual estimado" = último pago de cada liga pagando dividido para los meses que cubre.' => 'A liga de demonstração não é contada. "Receita mensal estimada" = último pagamento de cada liga pagante dividido pelos meses que ele cobre.',
    'La maduración se calcula con la fórmula de Mirwald (talla, talla sentado, peso, edad y género). Dos chicos de la misma edad pueden estar hasta {n} años distintos en su desarrollo: esto ayuda a no descartar a los que maduran tarde y a cuidar la carga de los que están en pleno estirón.' => 'A maturação é calculada com a fórmula de Mirwald (altura, altura sentado, peso, idade e gênero). Dois garotos da mesma idade podem diferir em até {n} anos no desenvolvimento: isso ajuda a não descartar os que amadurecem tarde e a cuidar da carga dos que estão em pleno estirão.',
