    'La página de la liga y su Resumen muestran los jugadores que cumplen años hoy (con su edad) y los equipos que se acercan a su aniversario (ponga la' => 'A página da liga e o seu Resumo mostram os jogadores que fazem aniversário hoje (com a idade) e as equipes que se aproximam do seu aniversário (informe a',
    'La página de su escuela con su propia dirección (www.suescuela.com) en vez de tuacademia.tukanec.com/su-escuela.' => 'A página da sua escola com o seu próprio endereço (www.suaescola.com) em vez de tuacademia.tukanec.com/sua-escola.',
    'La página de verificación del carnet (a la que se llega escaneando el QR) muestra la foto y la cédula parcialmente oculta, solo para identificar al participante.' => 'A página de verificação da carteirinha (à qual se chega escaneando o QR) mostra a foto e o documento parcialmente oculto, somente para identificar o participante.',
