    'Las facturas electrónicas' => 'As notas fiscais eletrônicas',
    'Las familias suben aquí la foto de su transferencia desde su portal. Revise que el dinero llegó y apruébelo: se emite el recibo.' => 'As famílias enviam aqui a foto da transferência pelo portal. Verifique se o dinheiro chegou e aprove: o recibo é emitido.',
    'Las fotos no van en el Excel: se suben después en cada equipo, o las sube cada delegado.' => 'As fotos não vão no Excel: são enviadas depois em cada equipe, ou cada delegado as envia.',
