    'Las fotos y los comprobantes no van en el Excel. Para subir datos desde Excel use' => 'As fotos e os comprovantes não vão no Excel. Para enviar dados pelo Excel, use',
    'Las ligas y escuelas le pagan su suscripción con tarjeta, y sus equipos y familias les pagan a ellas con TuAcademia de intermediario. Reporte y transferencias en' => 'As ligas e escolas pagam a assinatura a você com cartão, e suas equipes e famílias pagam a elas com a TuAcademia como intermediária. Relatório e transferências em',
