    'Las opciones son los goles de esa jornada (en básquet, los triples).' => 'As opções são os gols dessa rodada (no basquete, as cestas de três pontos).',
    'Las opciones son los jugadores presentes (si la vocalía los marcó) o las dos plantillas.' => 'As opções são os jogadores presentes (se a súmula os marcou) ou os dois elencos.',
    'Las reglas vienen llenas con los valores por defecto de la liga. Cámbielas solo si este campeonato es distinto (otra modalidad, otra duración, otro número de árbitros, etc.).' => 'As regras vêm preenchidas com os valores padrão da liga. Altere-as somente se este campeonato for diferente (outra modalidade, outra duração, outro número de árbitros etc.).',
