    'Llene este formulario y la liga queda funcionando con su administrador, su página pública y (si quiere) su primer campeonato. No hay que copiar archivos ni tocar el servidor.' => 'Preencha este formulário e a liga fica funcionando com o seu administrador, a sua página pública e (se quiser) o seu primeiro campeonato. Não é preciso copiar arquivos nem mexer no servidor.',
    'Lo asume la liga (el que paga ve el valor exacto; a usted le llega el valor menos la comisión)' => 'A liga assume (quem paga vê o valor exato; você recebe o valor menos a comissão)',
    'Lo básico (Equipos y jugadores con foto, Sorteo y fixture automático (todos contra todos, grupos, ida y vuelta), Llaves eliminatorias automáticas, Tabla de posiciones, goleadores y tarjetas, Suspensiones automáticas y sanciones…) viene en todos los planes. Marque los módulos que trae este plan:' => 'O básico (Equipes e jogadores com foto, Sorteio e tabela de jogos automáticos (todos contra todos, grupos, ida e volta), Chaves eliminatórias automáticas, Classificação, artilheiros e cartões, Suspensões automáticas e punições…) vem em todos os planos. Marque os módulos que este plano inclui:',
