    'Los XML que le llegan al correo con cada factura. Puede elegir varios a la vez o un' => 'Os XML que chegam ao seu e-mail com cada nota fiscal. Você pode escolher vários de uma vez ou um',
    'Los avisos NO le están llegando:' => 'Os avisos NÃO estão chegando até você:',
    'Los avisos por Telegram no le están llegando' => 'Os avisos pelo Telegram não estão chegando para você',
    'Los celulares solo los ve la liga (para entregar premios). No se publican.' => 'Os celulares só são vistos pela liga (para entregar prêmios). Não são publicados.',
    'Los cobros de' => 'As cobranças de',
    'Los competidores se inscriben solos (y pueden pagar con tarjeta). Además: imágenes para redes, hojas para imprimir, resultados en vivo y copiar para la nueva temporada.' => 'Os competidores se inscrevem sozinhos (e podem pagar com cartão). Além disso: imagens para redes, folhas para imprimir, resultados ao vivo e cópia para a nova temporada.',
    'Los comprobantes de' => 'Os comprovantes de',
    'Los datos' => 'Os dados',
    'Los datos de menores de {n} años se tratan con especial cuidado: su inscripción requiere la autorización y los datos del representante legal, y su foto no se publica sin permiso expreso.' => 'Os dados de menores de {n} anos são tratados com cuidado especial: a inscrição exige a autorização e os dados do responsável legal, e a foto não é publicada sem permissão expressa.',
    'Los datos se guardan en' => 'Os dados são armazenados em',
    'Los delegados envían desde su portal la foto de su transferencia o depósito. Revise que el dinero llegó a la cuenta y apruébelo: el pago y el recibo se registran solos. Los datos de la cuenta para pagar se escriben en' => 'Os delegados enviam pelo seu portal a foto da transferência ou do depósito. Verifique se o dinheiro chegou à conta e aprove-o: o pagamento e o recibo são registrados automaticamente. Os dados da conta para pagamento são escritos em',
    'Los delegados los ven al enviar el comprobante de su transferencia.' => 'Os delegados os veem ao enviar o comprovante da sua transferência.',
    'Los delegados piden desde su portal:' => 'Os delegados solicitam pelo seu portal:',
    'Los delegados pueden inscribir jugadores hasta' => 'Os delegados podem inscrever jogadores até',
    'Los delegados pueden pedir pases en línea' => 'Os delegados podem solicitar transferências online',
    'Los ejercicios de la escuela. El profesor los elige al planificar cada clase y los padres ven en el diario qué ejercicios hizo su hijo.' => 'Os exercícios da escola. O treinador os escolhe ao planejar cada aula e os pais veem no diário quais exercícios o filho fez.',
    'Los equipos no tienen jugadores registrados.' => 'As equipes não têm jogadores registrados.',
    'Los equipos se inscriben por internet y cada delegado registra a sus jugadores.' => 'As equipes se inscrevem pela internet e cada delegado registra os seus jogadores.',
    'Los equipos se inscriben por internet; cada delegado inscribe a sus jugadores, pide pases, reprogramaciones y apelaciones y ve su estado de cuenta.' => 'As equipes se inscrevem pela internet; cada delegado inscreve os seus jogadores, solicita transferências, reprogramações e recursos e vê o seu extrato.',
    'Los equipos y los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'As equipes e os pais pagam com cartão pelo celular, o recibo é emitido automaticamente e você vê cada pagamento no seu relatório.',
    'Los hinchas adivinan los resultados de los próximos partidos desde la página de la liga y suman puntos.' => 'Os torcedores adivinham os resultados das próximas partidas pela página da liga e somam pontos.',
    'Los hinchas pronostican los resultados gratis y compiten en una tabla. Sin apuestas.' => 'Os torcedores dão palpites nos resultados de graça e competem em uma classificação. Sem apostas.',
    'Los hinchas reciben en el celular cada gol, el resultado y los horarios de su equipo.' => 'Os torcedores recebem no celular cada gol, o resultado e os horários da sua equipe.',
    'Los impuestos solo se muestran desglosados en el reporte; consulte con su contador si su liga debe cobrarlos.' => 'Os impostos só são exibidos detalhados no relatório; consulte o seu contador se a sua liga deve cobrá-los.',
    'Los lugares donde entrenan (nombre y dirección).' => 'Os locais onde treinam (nome e endereço).',
    'Los límites y módulos se aplican solos a cada liga o escuela según su plan (en la prueba gratis tienen todo). {n} = sin límite. Un precio en {n} = ese período no se ofrece. En Ligas → Editar puede regalar módulos a una liga.' => 'Os limites e módulos são aplicados automaticamente a cada liga ou escola conforme o plano (no teste grátis têm tudo). {n} = sem limite. Um preço em {n} = esse período não é oferecido. Em Ligas → Editar você pode dar módulos de brinde a uma liga.',
    'Los manuales de ligas y de escuelas ya están en español, inglés, francés, portugués e italiano, con todo lo nuevo. Elija el idioma con el botón 🌐.' => 'Os manuais de ligas e de escolas já estão em espanhol, inglês, francês, português e italiano, com todas as novidades. Escolha o idioma com o botão 🌐.',
    'Los marcadores en vivo se actualizan solos cada {n} segundos.' => 'Os placares ao vivo se atualizam sozinhos a cada {n} segundos.',
    'Los módulos, uno por uno' => 'Os módulos, um por um',
    'Los padres inscriben a sus hijos desde la página de la escuela.' => 'Os pais inscrevem os filhos pela página da escola.',
    'Los padres inscriben a sus hijos por internet y ven asistencia, pagos, recibos, evaluaciones y libreta desde el celular.' => 'Os pais inscrevem os filhos pela internet e veem presença, pagamentos, recibos, avaliações e boletim pelo celular.',
    'Los padres llenan la ficha desde la página de la escuela. Llega a' => 'Os pais preenchem a ficha pela página da escola. Chega em',
    'Los padres pagan con tarjeta desde su celular y el pago se aplica solo.' => 'Os pais pagam com cartão pelo celular e o pagamento é aplicado automaticamente.',
    'Los padres pagan con tarjeta desde su celular, el recibo sale solo y usted ve cada pago en su reporte.' => 'Os pais pagam com cartão pelo celular, o recibo é emitido automaticamente e você vê cada pagamento no seu relatório.',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Os pais pagam com cartão; o recibo é emitido automaticamente. A TuAcademia transfere a você o valor cobrado menos a comissão do cartão (Cartão de crédito {n}% + IVA',
    'Los padres pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Os pais pagam com cartão; o recibo é emitido automaticamente. A TuAcademia transfere a você o valor cobrado menos a comissão do cartão (Cartão de crédito {n}% + IVA · Cartão de débito {n}% + IVA · Gestão administrativa da TuAcademia {n}%). Você escolhe se a comissão é assumida pela sua organização ou por quem paga.',
    'Los padres pagan las mensualidades con tarjeta de crédito o débito desde su celular; el recibo sale solo y usted ve cada pago en su reporte.' => 'Os pais pagam as mensalidades com cartão de crédito ou débito pelo celular; o recibo é emitido automaticamente e você vê cada pagamento no seu relatório.',
    'Los padres pueden ver las fotos' => 'Os pais podem ver as fotos',
    'Los padres ven el plan' => 'Os pais veem o plano',
    'Los pases en línea solo se piden mientras la inscripción de jugadores está' => 'As transferências on-line só podem ser solicitadas enquanto a inscrição de jogadores está',
    'Los pilotos con «categoría automática» entran a la primera que cumpla su cilindrada y su motor (atmosférico o turbo). Los turbo van a la categoría turbo aunque su cilindrada sea baja.' => 'Os pilotos com «categoria automática» entram na primeira que atender à sua cilindrada e ao seu motor (aspirado ou turbo). Os turbo vão para a categoria turbo mesmo que a cilindrada seja baixa.',
    'Los que carga el vocal en vivo aparecen aquí automáticamente.' => 'Os que o mesário carrega ao vivo aparecem aqui automaticamente.',
