    'Mientras la persona participe en la escuela y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Enquanto a pessoa participar da escola e, depois, pelo tempo necessário para conservar o histórico esportivo (campeões, estatísticas) e cumprir obrigações legais (por exemplo, contábeis e tributárias). A exclusão pode ser solicitada a qualquer momento (ponto {n}): nesse caso os dados pessoais são apagados e restam apenas as estatísticas sem nome.',
    'Mientras la persona participe en la liga y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Enquanto a pessoa participar da liga e, depois, pelo tempo necessário para conservar o histórico esportivo (campeões, estatísticas) e cumprir obrigações legais (por exemplo, contábeis e tributárias). A exclusão pode ser solicitada a qualquer momento (ponto {n}): nesse caso os dados pessoais são apagados e restam apenas as estatísticas sem nome.',
    'Mientras la persona participe en la organización y luego el tiempo necesario para conservar el historial deportivo (campeones, estadísticas) y cumplir obligaciones legales (por ejemplo, contables y tributarias). Se puede pedir la eliminación en cualquier momento (punto {n}): en ese caso los datos personales se borran y solo quedan las estadísticas sin nombre.' => 'Enquanto a pessoa participar da organização e, depois, pelo tempo necessário para conservar o histórico esportivo (campeões, estatísticas) e cumprir obrigações legais (por exemplo, contábeis e tributárias). A exclusão pode ser solicitada a qualquer momento (ponto {n}): nesse caso os dados pessoais são apagados e restam apenas as estatísticas sem nome.',
    'Mientras más afuera, mejor que el resto de su categoría en la escuela.' => 'Quanto mais para fora, melhor que o resto da sua categoria na escola.',
