    'Sus campeonatos federativos (inter-ligas) de cualquier deporte se crean en' => 'Seus campeonatos federativos (inter-ligas) de qualquer esporte são criados em',
    'Sus datos' => 'Seus dados',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA' => 'Seus times pagam com cartão de crédito ou débito pelo celular. A TuAcademia recebe o dinheiro por meio da Plux, aplica o pagamento, emite o recibo na hora e transfere o valor cobrado para a sua conta. Custo: Cartão de crédito {n}% + IVA',
    'Sus equipos pagan con tarjeta de crédito o débito desde su celular. TuAcademia recibe el dinero por medio de Plux, aplica el pago y emite el recibo al instante, y le transfiere lo cobrado a su cuenta. Costo: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%.' => 'Seus times pagam com cartão de crédito ou débito pelo celular. A TuAcademia recebe o dinheiro por meio da Plux, aplica o pagamento, emite o recibo na hora e transfere o valor cobrado para a sua conta. Custo: Cartão de crédito {n}% + IVA · Cartão de débito {n}% + IVA · Gestão administrativa da TuAcademia {n}%.',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Seus times pagam com cartão de crédito ou débito; o recibo é emitido automaticamente e você recebe a transferência na sua conta. Custo por transação: Cartão de crédito {n}% + IVA',
    'Sus equipos pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Seus times pagam com cartão de crédito ou débito; o recibo é emitido automaticamente e você recebe a transferência na sua conta. Custo por transação: Cartão de crédito {n}% + IVA · Cartão de débito {n}% + IVA · Gestão administrativa da TuAcademia {n}%. Você escolhe se a comissão fica por conta da sua organização ou de quem paga.',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA' => 'Seus times pagam com cartão; o recibo é emitido automaticamente. A TuAcademia transfere o valor cobrado menos a comissão do cartão (Cartão de crédito {n}% + IVA',
    'Sus equipos pagan con tarjeta; el recibo sale solo. TuAcademia le transfiere lo cobrado menos la comisión de la tarjeta (Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%). Usted elige si la comisión la asume su organización o el que paga.' => 'Seus times pagam com cartão; o recibo é emitido automaticamente. A TuAcademia transfere o valor cobrado menos a comissão do cartão (Cartão de crédito {n}% + IVA · Cartão de débito {n}% + IVA · Gestão administrativa da TuAcademia {n}%). Você escolhe se a comissão fica por conta da sua organização ou de quem paga.',
    'Sus equipos pagan inscripciones, arbitrajes y multas con' => 'Seus times pagam inscrições, arbitragens e multas com',
    'Sus equipos y familias le pagan con tarjeta de crédito o débito desde su celular; el sistema aplica el pago, emite el recibo y usted ve todo en su reporte de pagos.' => 'Seus times e famílias pagam com cartão de crédito ou débito pelo celular; o sistema aplica o pagamento, emite o recibo e você vê tudo no seu relatório de pagamentos.',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA' => 'Suas famílias pagam com cartão de crédito ou débito; o recibo é emitido automaticamente e você recebe a transferência na sua conta. Custo por transação: Cartão de crédito {n}% + IVA',
    'Sus familias pagan con tarjeta de crédito o débito; el recibo sale solo y usted recibe la transferencia en su cuenta. Costo por transacción: Tarjeta de crédito {n}% + IVA · Tarjeta de débito {n}% + IVA · Gestión administrativa de TuAcademia {n}%. Usted elige si la comisión la asume su organización o el que paga.' => 'Suas famílias pagam com cartão de crédito ou débito; o recibo é emitido automaticamente e você recebe a transferência na sua conta. Custo por transação: Cartão de crédito {n}% + IVA · Cartão de débito {n}% + IVA · Gestão administrativa da TuAcademia {n}%. Você escolhe se a comissão fica por conta da sua organização ou de quem paga.',
    'Sus familias pagan las mensualidades con' => 'Suas famílias pagam as mensalidades com',
    'Sus goles y tarjetas anteriores quedan con su equipo anterior. El sistema revisa el cupo y la categoría del equipo que lo recibe.' => 'Seus gols e cartões anteriores permanecem com o time anterior. O sistema verifica a vaga e a categoria do time que o recebe.',
