    'Sí: cada liga y cada campeonato tienen su dirección corta ({n}:{n}/su-liga/apertura) y, pagando el plan Profesional por {n} año, le damos un dominio propio (www.suliga.com).' => 'Sim: cada liga e cada campeonato têm seu endereço curto ({n}:{n}/su-liga/apertura) e, pagando o plano Profissional por {n} ano, oferecemos um domínio próprio (www.sualiga.com).',
    'Sí: fútbol {n}, {n}, {n}, {n}, {n}, {n} o personalizado, indor, ecuavóley por sets y básquet. Cada campeonato define sus jugadores, tiempos, árbitros y reglas.' => 'Sim: futebol {n}, {n}, {n}, {n}, {n}, {n} ou personalizado, futsal, ecuavóley por sets e basquete. Cada campeonato define seus jogadores, tempos, árbitros e regras.',
    'Sí: su escuela tiene su dirección corta ({n}:{n}/su-escuela) y, pagando el plan Escuela Completo por {n} año, le damos un dominio propio (www.suescuela.com).' => 'Sim: sua escola tem seu endereço curto ({n}:{n}/su-escuela) e, pagando o plano Escola Completo por {n} ano, oferecemos um domínio próprio (www.suaescola.com).',
