    'Carrera de un día: 1. Vuelta por etapas: el número de etapas. Cada carrera puede tener las suyas.' => 'Corrida de um dia: 1. Volta por etapas: o número de etapas. Cada corrida pode ter as suas.',
    'XCO: 1. Descenso: normalmente 2 bajadas. Enduro: los tramos. Cada carrera puede tener las suyas.' => 'XCO: 1. Downhill: normalmente 2 descidas. Enduro: os trechos. Cada corrida pode ter as suas.',
    'Mejor joven: hasta cuántos años' => 'Melhor jovem: até quantos anos',
    'UCI: sub-23 = hasta 22 años cumplidos en el año. 0 = sin clasificación del joven.' => 'UCI: sub-23 = até 22 anos completados no ano. 0 = sem classificação do jovem.',
