    'el tiempo del equipo se toma en su 3.er corredor.' => 'o tempo da equipe é tomado no seu 3.º corredor.',
    'Critérium:' => 'Critério:',
    'gana quien suma más puntos. Límite %: los que llegan más allá de ese porcentaje del tiempo del ganador quedan fuera de control (OTL) y salen de la general (UCI usa entre 8 % y 20 % según la etapa).' => 'vence quem soma mais pontos. Limite %: quem chega além dessa porcentagem do tempo do vencedor fica fora do tempo (OTL) e sai da geral (a UCI usa entre 8 % e 20 % conforme a etapa).',
    'Ruta:' => 'Estrada:',
    'escriba el tiempo real de llegada de cada uno; el sistema aplica solo el mismo tiempo del grupo, las bonificaciones de meta, los puntos y el fuera de control según la configuración de cada etapa. En ⚑ cargue las bonificaciones y puntos de los sprints intermedios y los puntos de montaña.' => 'escreva o tempo real de chegada de cada um; o sistema aplica sozinho o mesmo tempo do grupo, as bonificações, os pontos e o tempo limite conforme a configuração de cada etapa. Em ⚑ carregue as bonificações e pontos dos sprints intermediários e os pontos de montanha.',
    'XCO:' => 'XCO:',
    'en «vueltas» ponga las vueltas que completó; si el comisario lo retiró por la regla del 80 % o fue doblado, ponga su tiempo y sus vueltas (queda clasificado detrás, con «−N vueltas»).' => 'em «voltas» coloque as voltas completadas; se o comissário o retirou pela regra dos 80 % ou foi ultrapassado, coloque seu tempo e voltas (fica classificado atrás, com «−N voltas»).',
