    'Ruta: etapas en línea, contrarreloj y critérium, bonificaciones, mismo tiempo del grupo, fuera de control y clasificaciones de puntos, montaña, mejor joven y equipos. Nuevos deportes: ciclismo de pista (velocidad, keirin, persecución, puntos, scratch, eliminación, tempo y omnium), BMX Racing (motos, cuartos, semis y final), BMX Freestyle (Park y Flatland con jueces) y MTB (cross-country por vueltas, descenso y enduro).' => 'Estrada: etapas em linha, contrarrelógio e critério, bonificações, mesmo tempo do grupo, tempo limite e classificações de pontos, montanha, melhor jovem e equipes. Novos esportes: ciclismo de pista (velocidade, keirin, perseguição, pontos, scratch, eliminação, tempo e omnium), BMX Racing (baterias, quartas, semis e final), BMX Freestyle (Park e Flatland com juízes) e MTB (cross-country por voltas, downhill e enduro).',
