    'El sistema ahora se arma por deporte: Fútbol, Básquet, Vóley, Ecuavóley, Ciclismo, Deportes de combate, Deportes de raqueta, Natación, Atletismo, Bolos y Automovilismo. Agregue a su cuenta los deportes que necesite con descuento desde el segundo módulo; todo queda en el mismo panel. Cada deporte pide sus propios datos y documentos (licencia, certificado médico, peso, grado…).' => 'O sistema agora é montado por esporte: Futebol, Basquete, Vôlei, Ecuavôlei, Ciclismo, Esportes de combate, Esportes de raquete, Natação, Atletismo, Boliche e Automobilismo. Adicione à sua conta os esportes de que precisa com desconto a partir do segundo módulo; tudo fica no mesmo painel. Cada esporte pede seus próprios dados e documentos (licença, atestado médico, peso, graduação…).',
    // (v35) módulos separados
    'Deportes de raqueta' => 'Esportes de raquete',
    'Atletismo' => 'Atletismo',
    'Automovilismo' => 'Automobilismo',
    'Tenis, pádel y tenis de mesa: llaves con cabezas de serie, marcador por sets, todos contra todos y ranking.' => 'Tênis, padel e tênis de mesa: chaves com cabeças de chave, placar por sets, todos contra todos e ranking.',
    'Pruebas por estilo y distancia (libre, espalda, pecho, mariposa, combinado y relevos), por edad y rama, con medallero y puntos por club.' => 'Provas por estilo e distância (livre, costas, peito, borboleta, medley e revezamentos), por idade e naipe, com quadro de medalhas e pontos por clube.',
    'Carreras, vallas, saltos, lanzamientos y relevos por categoría y rama, con medallero, puntos por club y mejores marcas.' => 'Corridas, barreiras, saltos, arremessos e revezamentos por categoria e naipe, com quadro de medalhas, pontos por clube e melhores marcas.',
    'Jornadas con líneas, handicap automático, récords y clasificación individual y por clubes.' => 'Rodadas com linhas, handicap automático, recordes e classificação individual e por clubes.',
    'Autocross por mangas con categorías por cilindrada y motor, conos, penalizaciones y campeonato por puntos o tiempo.' => 'Autocross por baterias com categorias por cilindrada e motor, cones, penalidades e campeonato por pontos ou tempo.',
