    'Tenis, Pádel, Tenis de mesa, Squash' => 'Tênis, Padel, Tênis de mesa, Squash',
    'Tenis, pádel, tenis de mesa y squash: llaves con cabezas de serie, grupos, consolación, Monrad, escalera del club, marcador por sets o games a 11 y ranking del circuito.' => 'Tênis, padel, tênis de mesa e squash: chaves com cabeças de chave, grupos, consolação, Monrad, escada do clube, placar por sets ou games de 11 e ranking do circuito.',
    'Torneos por sistema suizo (Buchholz), todos contra todos o llave, con ELO, categorías Sub 10 a Sub 18 y ranking del circuito.' => 'Torneios no sistema suíço (Buchholz), todos contra todos ou chave, com rating, categorias Sub 10 a Sub 18 e ranking do circuito.',
    'Torneos de videojuegos 1 vs 1 o 2 vs 2 (eFootball, FIFA/FC y otros): grupos, llaves con penales, tabla por goles y ranking.' => 'Torneios de videogame 1 contra 1 ou 2 contra 2 (eFootball, FIFA/FC e outros): grupos, chaves com pênaltis, tabela por gols e ranking.',
    'Competencias con las reglas de la IWF: categorías de peso corporal, 3 intentos de arranque y 3 de envión, total, medallero y puntos por club.' => 'Competições com as regras da IWF: categorias de peso corporal, 3 tentativas de arranco e 3 de arremesso, total, quadro de medalhas e pontos por clube.',
    'Triatlón, duatlón y acuatlón: tiempo por segmento y transiciones, clasificación general, por rama y por grupo de edad.' => 'Triatlo, duatlo e aquatlo: tempo por segmento e transições, classificação geral, por sexo e por faixa etária.',
    'Balonmano (handball) 7 contra 7: goles, goles de 7 metros, exclusiones de 2 minutos, amonestaciones y descalificaciones, vocalía en vivo, tabla 2-1-0 y goleadores.' => 'Handebol 7 contra 7: gols, gols de 7 metros, exclusões de 2 minutos, advertências e desqualificações, súmula ao vivo, tabela 2-1-0 e artilheiros.',
    'Béisbol (9 entradas) y softbol (7 entradas): carreras por entrada, hits, errores, jonrones y ponches, pizarra del partido, vocalía en vivo y tabla de ganados.' => 'Beisebol (9 entradas) e softbol (7 entradas): corridas por entrada, rebatidas, erros, home runs e strikeouts, placar da partida, súmula ao vivo e tabela de vitórias.',
    'Pista y campo con las reglas de World Athletics (series y final, viento, concursos con intentos, salto alto y garrocha por alturas, heptatlón y decatlón) y carreras de ruta, trail y cross con tiempo de chip, grupos de edad, diplomas y equipos.' => 'Pista e campo com as regras da World Athletics (eliminatórias e final, vento, provas de campo com tentativas, altura e vara por alturas, heptatlo e decatlo) e corridas de rua, trail e cross com chip, faixas etárias, certificados e equipes.',
    'Squash · Games a 11: grupos y luego llave, Monrad con todos los puestos, escalera del club y ranking.' => 'Squash · Games de 11: grupos e depois chave, Monrad com todas as posições, escada do clube e ranking.',
    'Ajedrez · Sistema suizo con Buchholz, ELO y todos contra todos.' => 'Xadrez · Sistema suíço com Buchholz, rating e todos contra todos.',
    'E-sports · eFootball 1 vs 1: grupos, llave con penales y tercer puesto.' => 'E-sports · eFootball 1 contra 1: grupos, chave com pênaltis e 3º lugar.',
    'Carreras de ruta, trail y cross · 10K con tiempo de chip, grupos de edad, equipos, buscador por dorsal y diplomas.' => 'Corridas de rua, trail e cross · 10K com chip, faixas etárias, equipes, busca por número e certificados.',
    'Levantamiento de pesas · Arranque y envión con 3 intentos, total y peso corporal (IWF).' => 'Levantamento de peso · Arranco e arremesso com 3 tentativas, total e peso corporal (IWF).',
    'Triatlón · Natación, transiciones, ciclismo y carrera, con grupos de edad.' => 'Triatlo · Natação, transições, ciclismo e corrida, com faixas etárias.',
