    'Sistema suizo (por rondas)' => 'Sistema suíço (por rodadas)',
    'Escalera de desafíos (ranking del club)' => 'Escada de desafios (ranking do clube)',
    'El que pierde queda fuera. Cabezas de serie separados y pases directos repartidos.' => 'Quem perde está fora. Cabeças de chave separados e byes distribuídos.',
    'Todos juegan contra todos; gana la tabla.' => 'Todos jogam contra todos; a tabela decide.',
    'Grupos de 3 a 5 (todos contra todos) y los primeros de cada grupo pasan a una llave final. Es el formato de los nacionales de squash.' => 'Grupos de 3 a 5 (todos contra todos) e os primeiros de cada grupo vão para uma chave final. É o formato dos nacionais de squash.',
    'Llave principal y una llave de consolación (plate) para los que pierden su primer partido: todos juegan al menos dos.' => 'Chave principal e uma chave de consolação (plate) para quem perde a primeira partida: todos jogam pelo menos duas.',
    'Nadie queda fuera: ganadores y perdedores siguen jugando en sub-llaves hasta definir todos los puestos (1.º al último).' => 'Ninguém fica de fora: vencedores e perdedores seguem jogando em subchaves até definir todas as posições (do 1º ao último).',
    'Por rondas: en cada ronda se empareja a los de igual puntaje sin repetir rival. Ideal para ajedrez y para muchos inscritos.' => 'Por rodadas: em cada rodada emparelham-se os de mesma pontuação sem repetir adversário. Ideal para xadrez e muitos inscritos.',
    'Ranking permanente del club: se desafía a alguien hasta N puestos arriba; si gana, toma su puesto.' => 'Ranking permanente do clube: desafia-se alguém até N posições acima; se vencer, assume a posição dele.',
