    'Suma los puntos de todos los campeonatos de {s} de su cuenta, por categoría (mismo nombre de categoría). Cada campeonato da puntos según el puesto final, multiplicados por su factor (por ejemplo: nacional 100 %, regional 50 %). Se cambian en «Reglas y configuración».' => 'Soma os pontos de todos os campeonatos de {s} da sua conta, por categoria (mesmo nome). Cada campeonato dá pontos conforme a posição final, multiplicados pelo seu fator (ex.: nacional 100 %, regional 50 %). Altere em «Regras e configuração».',
