    'Son los valores con los que empieza cada campeonato nuevo de este deporte en todas las cuentas. Deje vacío para usar el valor de fábrica (entre paréntesis). Cada cuenta puede cambiarlos después en su campeonato.' => 'São os valores com que começa cada campeonato novo deste esporte em todas as contas. Deixe vazio para usar o valor de fábrica (entre parênteses). Cada conta pode mudá-los depois no seu campeonato.',
