    'Nombre, cédula, foto, fecha de nacimiento y club ya están en cada ficha: aquí van los datos propios del deporte.' => 'Nome, documento, foto, data de nascimento e clube já estão em cada ficha: aqui vão os dados próprios do esporte.',
    'Nuevo documento (ej: Ficha de la federación)' => 'Novo documento (ex.: ficha da federação)',
    'Para quitar un documento, borre su nombre. Con «tiene vencimiento» se pide la fecha y, cuando pasa, vuelve a aparecer como faltante (ej: certificado médico anual).' => 'Para remover um documento, apague o nome. Com «tem vencimento» pede-se a data e, quando vence, volta a aparecer como faltante (ex.: atestado médico anual).',
    'Se piden en la ficha del jugador, del competidor o del alumno de este deporte y en la inscripción en línea. Lo' => 'São pedidos na ficha do jogador, competidor ou aluno deste esporte e na inscrição on-line. O',
    'que falte aparece como «⚠ falta» en las listas, y en la inscripción en línea no se puede enviar sin eso.' => 'que faltar aparece como «⚠ falta» nas listas, e a inscrição on-line não pode ser enviada sem isso.',
    'Para que el panel siga funcionando sin interrupciones, renueve antes de esa fecha.' => 'Para que o painel continue funcionando sem interrupções, renove antes dessa data.',
    '⏰ Su suscripción de TuAcademia vence en {s} días ({s})' => '⏰ Sua assinatura do TuAcademia vence em {s} dias ({s})',
    'Activa hasta el {s} (faltan {s} días)' => 'Ativa até {s} (faltam {s} dias)',
    'Puede crear {n} campeonato a la vez (en curso) · lleva {n} · no le quedan más' => 'Pode criar {n} campeonato por vez (em andamento) · tem {n} · não restam mais',
    'El sistema se vende por deporte. Cada cuenta tiene sus módulos; quien compra más de uno lo ve todo junto en el mismo panel. Aquí maneja precios, requisitos, reglas por defecto, qué módulos tiene cada cuenta y las demos de cada deporte.' => 'O sistema é vendido por esporte. Cada conta tem seus módulos; quem compra mais de um vê tudo junto no mesmo painel. Aqui você gerencia preços, requisitos, regras padrão, quais módulos cada conta tem e as demos de cada esporte.',
    '(natación, atletismo, ciclismo de pista, bmx racing, bmx freestyle, carreras de ruta, trail y cross, levantamiento de pesas, triatlón, duatlón y acuatlón)' => '(natação, atletismo, ciclismo de pista, BMX racing, BMX freestyle, corridas de rua, trail e cross, levantamento de peso, triatlo, duatlo e aquatlo)',
    '(tenis, pádel, tenis de mesa, squash, artes marciales, boxeo, ajedrez, e-sports)' => '(tênis, padel, tênis de mesa, squash, artes marciais, boxe, xadrez, e-sports)',
    '(Fútbol, Indor, Ecuavóley, Básquet, Balonmano, Béisbol y softbol)' => '(Futebol, Futsal, Ecuavôlei, Basquete, Handebol, Beisebol e softbol)',
    'Béisbol, Softbol' => 'Beisebol, Softbol',
    'Boxeo, Artes marciales' => 'Boxe, Artes marciais',
