    '· Carrera con clasificación general, por rama y por edad.' => '· Corrida com classificação geral, por sexo e por idade.',
    'en demo · 🏆 {n} campeonatos · 🎓 {n} grupos' => 'em demo · 🏆 {n} campeonatos · 🎓 {n} turmas',
