    'Varones Libre' => 'Masculino Livre',
    'Precios en dólares. En la demo tiene todos los módulos (el fixture para imprimir y el esquema del campeonato son exclusivos del plan Profesional). ¿Necesita algo especial? Consúltenos.' => 'Preços em dólares. Na demo você tem todos os módulos (a tabela para imprimir e o esquema do campeonato são exclusivos do plano Profissional). Precisa de algo especial? Fale conosco.',
    '· 🎓 Escuela multideporte (fútbol, básquet, vóley, boxeo, natación, taekwondo y tenis) ·' => '· 🎓 Escola multiesportiva (futebol, basquete, vôlei, boxe, natação, taekwondo e tênis) ·',
    'usa las reglas de la UCI (etapas, mismo tiempo, bonificaciones, puntos, montaña, mejor joven y equipos); en' => 'usa as regras da UCI (etapas, mesmo tempo, bonificações, pontos, montanha, melhor jovem e equipes); em',
