    'Fútbol, indor, vóley, ecuavóley, básquet, balonmano, béisbol y deportes individuales: carreras, tenis, pádel, squash, tenis de mesa, artes marciales, boxeo, ajedrez, e-sports, bolos, natación, atletismo, carreras de ruta, pesas y triatlón; y olimpiadas multideportivas.' => 'Futebol, futsal, vôlei, ecuavôlei, basquete, handebol, beisebol e esportes individuais: corridas, tênis, padel, squash, tênis de mesa, artes marciais, boxe, xadrez, e-sports, boliche, natação, atletismo, corridas de rua, levantamento de peso e triatlo; e olimpíadas multiesportivas.',
    // v37
    'Olimpiadas' => 'Olimpíadas',
    '🏅 Olimpiadas' => '🏅 Olimpíadas',
    'Olimpiadas y juegos multideportivos' => 'Olimpíadas e jogos multiesportivos',
    'Olimpiadas interempresas, interbancarias o intercolegiales: varios deportes a la vez, delegaciones que inscriben a su gente con su propio enlace, una ficha por deportista, medallero general, tabla de puntos configurable y administradores por evento.' => 'Olimpíadas entre empresas, bancos ou escolas: vários esportes ao mesmo tempo, delegações que inscrevem seu pessoal com seu próprio link, uma ficha por atleta, quadro geral de medalhas, tabela de pontos configurável e administradores por evento.',
    'Juegos multideportivos: delegaciones y medallero' => 'Jogos multiesportivos: delegações e medalhas',
    'Eventos multideportivos: disciplinas, delegaciones, deportistas, medallero y configuración.' => 'Eventos multiesportivos: modalidades, delegações, atletas, medalhas e configuração.',
    'Administrador de evento (olimpiadas)' => 'Administrador de evento (olimpíadas)',
    'Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Só os eventos de olimpíadas atribuídos a ele: configuração, modalidades, delegações, atletas, resultados dos seus campeonatos e medalhas.',
    'Administrador de evento (olimpiadas) — Solo los eventos de olimpiadas que se le asignan: configuración, disciplinas, delegaciones, deportistas, resultados de sus campeonatos y medallero.' => 'Administrador de evento (olimpíadas) — Só os eventos de olimpíadas atribuídos a ele: configuração, modalidades, delegações, atletas, resultados dos seus campeonatos e medalhas.',
    '🏅 Olimpiadas y juegos multideportivos' => '🏅 Olimpíadas e jogos multiesportivos',
    'Organice olimpiadas interempresas, interbancarias, intercolegiales o de barrio: varios deportes a la vez, cada empresa o colegio como una' => 'Organize olimpíadas entre empresas, bancos, escolas ou de bairro: vários esportes ao mesmo tempo, cada empresa ou escola como uma',
